create function public.create_household(household_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare new_id uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; insert into public.households(name,owner_id) values(trim(household_name),auth.uid()) returning id into new_id; insert into public.household_members(household_id,user_id,role) values(new_id,auth.uid(),'owner'); return new_id; end $$;
create function public.create_household_invite(target_household_id uuid) returns text language plpgsql security definer set search_path='' as $$ declare invite_code text; begin if not exists(select 1 from public.households where id=target_household_id and owner_id=auth.uid()) then raise exception 'Only the owner can invite members'; end if; invite_code := upper(substr(encode(gen_random_bytes(8),'hex'),1,10)); insert into public.household_invites(household_id,code,created_by,expires_at) values(target_household_id,invite_code,auth.uid(),now()+interval '7 days'); return invite_code; end $$;
create function public.join_household(invite_code text) returns uuid language plpgsql security definer set search_path='' as $$ declare invite public.household_invites%rowtype; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into invite from public.household_invites where code=upper(trim(invite_code)) and expires_at>now() and use_count<max_uses for update; if invite.id is null then raise exception 'Invite is invalid or expired'; end if; insert into public.household_members(household_id,user_id,role) values(invite.household_id,auth.uid(),'member') on conflict do nothing; update public.household_invites set use_count=use_count+1 where id=invite.id; return invite.household_id; end $$;
revoke all on function public.create_household(text),public.create_household_invite(uuid),public.join_household(text) from public;
grant execute on function public.create_household(text),public.create_household_invite(uuid),public.join_household(text) to authenticated;
